package constants

// RP-7: deposits through MagiDeposit (l1-deposit/src/MagiDeposit.sol) credit
// the Magi recipient its Deposit log names. The bridge accepts the log only
// from the address the contract has when deployed for the bridge's own vault:
// CREATE2 through the deterministic deployment proxy with salt 0 and init code
// DepositCreationCode ++ abi.encode(vault). A CREATE2 address commits to the
// init code, so code at that address is this contract with that vault.
//
// DepositCreationCode is the creation bytecode built with l1-deposit's pinned
// settings (solc 0.8.33, cancun, optimizer 200 runs, no CBOR metadata);
// keccak256 = DepositCreationCodeHash, which l1-deposit's tests also pin.
const (
	Create2DeployerHex      = "4e59b44847b379578588920ca78fbf26c0b4956c"
	DepositEventSigHex      = "ef519b7eb82aaf6ac376a6df2d793843ebfd593de5f1a0601d3cc6ab49ebb395" // Deposit(address,address,uint256,string)
	DepositCreationCodeHash = "14392c96a95bc649b2b82d231436c17e70a3fa11ee2000545193d00aa14b713b"
	// MaxDepositPairDistance: how far before a token Deposit log its
	// transferFrom's Transfer log may be (only the token's own logs come in
	// between).
	MaxDepositPairDistance = 4
	// MaxDepositRecipientLen mirrors MagiDeposit's recipient bound.
	MaxDepositRecipientLen = 128
)

const DepositCreationCode = ""
